import { select, checkbox, field, htmlEscape } from "../tool-core.js";export default {form: `<p style="font-size:14px;color:var(--body);margin-bottom:12px">Compress and convert images locally in your browser. No upload — all processing uses Canvas API.</p><div class="field-grid">${select({ id: "icFormat", label: "Output format", options: [{label:"JPEG (smaller, no transparency)",value:"image/jpeg"},{label:"PNG (lossless, transparency)",value:"image/png"},{label:"WebP (best compression)",value:"image/webp"}], value: "image/webp" })}${field({ id: "icQuality", label: "Quality (0-100)", type: "number", value: "80", attrs: "min=1 max=100" })}</div><div class="field-grid">${field({ id: "icMaxWidth", label: "Max width (px, 0=keep)", type: "number", value: "1200" })}${field({ id: "icMaxHeight", label: "Max height (px, 0=keep)", type: "number", value: "0" })}</div><div class="field-grid"><label class="upload-btn" style="display:inline-block;padding:10px 20px;background:var(--primary);color:#fff;border-radius:6px;cursor:pointer;font-weight:600;font-size:14px">Choose image<input type="file" id="icFile" accept="image/*" style="display:none"></label><span id="icFileName" style="font-size:13px;color:var(--muted);margin-left:8px">No file selected</span></div>`,generate(root) {const format = root.querySelector("#icFormat").value;const quality = Math.min(100, Math.max(1, parseInt(root.querySelector("#icQuality").value) || 80)) / 100;const maxW = parseInt(root.querySelector("#icMaxWidth").value) || 0;const maxH = parseInt(root.querySelector("#icMaxHeight").value) || 0;const fileInput = root.querySelector("#icFile");const nameSpan = root.querySelector("#icFileName");const output = ["// Image Compressor & Converter","// Select an image file to compress. All processing is local.","// Output format: " + format,"// Quality: " + Math.round(quality * 100) + "%",maxW ? "// Max width: " + maxW + "px" : "",maxH ? "// Max height: " + maxH + "px" : "","","// The compressed image will appear in the preview.","// Right-click the preview to save, or use the download button.","// For batch processing, use a script with the same Canvas approach:","// 1. Load image → 2. Draw on canvas → 3. canvas.toBlob() → 4. Download"].filter(Boolean).join("\n");if (fileInput) {fileInput.addEventListener("change", () => {const file = fileInput.files[0];if (file) {nameSpan.textContent = `${file.name} (${(file.size / 1024).toFixed(1)} KB)`;const reader = new FileReader();reader.onload = (e) => {const img = new Image();img.onload = () => {let w = img.width, h = img.height;if (maxW && w > maxW) { h = Math.round(h * maxW / w); w = maxW; }if (maxH && h > maxH) { w = Math.round(w * maxH / h); h = maxH; }const canvas = document.createElement("canvas");canvas.width = w; canvas.height = h;const ctx = canvas.getContext("2d");ctx.drawImage(img, 0, 0, w, h);const preview = root.querySelector("[data-role='preview']");if (preview) {canvas.toBlob((blob) => {const url = URL.createObjectURL(blob);const sizeKB = (blob.size / 1024).toFixed(1);preview.innerHTML = `<div style="text-align:center"><img src="${url}" style="max-width:100%;max-height:300px;border-radius:8px;border:1px solid #e5e7eb"><div style="margin-top:6px;font-size:12px;color:#6b7280">${w}x${h}px &middot; ${sizeKB} KB &middot; ${format.split("/")[1].toUpperCase()}</div><a href="${url}" download="compressed.${format.split("/")[1]}" style="display:inline-block;margin-top:8px;font-size:13px;color:var(--primary-active)">Download</a></div>`;}, format, quality);}};img.src = e.target.result;};reader.readAsDataURL(file);}});}return { output, preview: `<div style="padding:20px;border:2px dashed #d1d5db;border-radius:10px;text-align:center;color:#6b7280;font-size:14px" data-role="preview">Select an image to compress</div>` };}};